def melt_plot():
    # Heating of ice from t0 < 0 to 0 °C, plateau while melting, then water warms to t3.
    return {"kind": "plot", "x": [0, 'a + b + c2 + 2'], "y": ['t0 - 5', 't3 + 10'], "lines": [{"points": [[0, 't0'], ['a', 0], ['a + b', 0], ['a + b + c2', 't3']]}], "axes": {"x": 'τ, мин', "y": 't, °C'}}

